import math
from typing import Optional, Tuple

def classify_and_predict(a: float, b: float, p0: Tuple[float, float],
                         eps: float = 1e-6) -> dict:
    """Classify a co-adaptation loop and predict its convergence.

    Computes the contraction factor q = 1 - a - b and returns the stability
    regime, the predicted consensus value (b*h0 + a*d0)/(a+b) when applicable,
    and the number of rounds to reach |e_n| <= eps. All in O(1).
    """
    q = 1.0 - a - b
    aq = abs(q)
    s = a + b
    if math.isclose(s, 1.0):
        regime = "critically_damped"
    elif aq < 1.0:
        regime = "convergent"
    elif math.isclose(aq, 1.0):
        regime = "marginal"
    else:
        regime = "divergent"

    consensus: Optional[float] = None
    if not math.isclose(s, 0.0):
        consensus = (b * p0[0] + a * p0[1]) / s

    e0 = abs(p0[0] - p0[1])
    rounds: Optional[int] = None
    if e0 <= eps:
        rounds = 0
    elif math.isclose(aq, 0.0):
        rounds = 1
    elif aq < 1.0:
        rounds = math.ceil(math.log(eps / e0) / math.log(aq))

    return {"q": q, "abs_q": aq, "total_gain": s, "regime": regime,
            "consensus": consensus, "rounds_to_eps": rounds}

